-- Fresh installations contain the built-in v2 sheet from historical migrations.
-- Normalize only that exact known definition before removing templates.
-- The table may already be absent on installations that completed the removal.
DO $$
BEGIN
  IF to_regclass('character_templates') IS NOT NULL THEN
    LOCK TABLE "character_templates" IN ACCESS EXCLUSIVE MODE;
    UPDATE "character_templates"
      SET "version" = 4, "schema" = '{"title":"Tales from the Loop — Kid","sections":[{"key":"identity","label":"Identity"},{"key":"attributes","label":"Attributes"},{"key":"skills","label":"Skills"},{"key":"story","label":"Story and equipment"},{"key":"conditions","label":"Conditions"}],"fields":[{"key":"age","label":"Age","section":"identity","type":"number","required":true,"min":10,"max":19},{"key":"type","label":"Type","section":"identity","type":"select","required":true,"options":["BOOKWORM","COMPUTER_GEEK","JOCK","POPULAR_KID","ROCKER","TROUBLEMAKER","WEIRDO"]},{"key":"body","label":"Body","section":"attributes","type":"number","min":1,"max":5},{"key":"tech","label":"Tech","section":"attributes","type":"number","min":1,"max":5},{"key":"heart","label":"Heart","section":"attributes","type":"number","min":1,"max":5},{"key":"mind","label":"Mind","section":"attributes","type":"number","min":1,"max":5},{"key":"force","label":"Force","section":"skills","type":"number","min":0,"max":5},{"key":"move","label":"Move","section":"skills","type":"number","min":0,"max":5},{"key":"sneak","label":"Sneak","section":"skills","type":"number","min":0,"max":5},{"key":"tinker","label":"Tinker","section":"skills","type":"number","min":0,"max":5},{"key":"program","label":"Program","section":"skills","type":"number","min":0,"max":5},{"key":"calculate","label":"Calculate","section":"skills","type":"number","min":0,"max":5},{"key":"contact","label":"Contact","section":"skills","type":"number","min":0,"max":5},{"key":"charm","label":"Charm","section":"skills","type":"number","min":0,"max":5},{"key":"lead","label":"Lead","section":"skills","type":"number","min":0,"max":5},{"key":"investigate","label":"Investigate","section":"skills","type":"number","min":0,"max":5},{"key":"comprehend","label":"Comprehend","section":"skills","type":"number","min":0,"max":5},{"key":"empathize","label":"Empathize","section":"skills","type":"number","min":0,"max":5},{"key":"drive","label":"Drive","section":"st